"""S1 P0 cases, part two: C (diabetes), D (blood thinner), G (ate breakfast), H (possible pregnancy), J (the 'high potassium' that wasn't). Source: walkthrough Part 12 / 17; see s1.py."""
from lib import D, E, H, O, P, R, S, bad, case, debrief, history, person

CASES = {}

# ---------------------------------------------------------------------------------------------------------------- VAR-S1-C
CASES["VAR-S1-C"] = case(
    "VAR-S1-C", "Patient S1-C - diabetes", "S1",
    person("Mrs", "Nasreen Akhtar", "F", 55, "primary school cook", 11, 2, "518842"),
    {"setting": "pre-assessment", "time_now": "08:00", "surgery_time": "10:00",
     "summary": "Mrs Nasreen, 55, has type 2 diabetes treated with metformin and gliclazide. HbA1c was 58 mmol/mol two months ago and her finger-prick sugar this morning is 7.8. Variant C2 has HbA1c 82, sugar 13.4 and ketones 0.4."},
    history("Attacks of pain under the ribs after meals; none this week.", red_flags="No fever, no yellow eyes.", past="Type 2 diabetes for eight years.",
            medicines="Metformin and gliclazide. She has not taken them this morning.", last_food="Dinner at 20:00 yesterday.", last_drink="Water at 06:00.", pregnancy="Past the menopause.", origin={"complaint": "authored"}),
    [O("08:00", 74, 132, 80, 14, 98, 36.8, note="Baseline vital signs, all normal.", origin="authored")],
    [E("ex.abdomen", "abdomen", "Soft; no tenderness."), E("ex.feet", "feet", "No foot ulcers.")],
    [R("lab.hba1c", "HbA1c", 58, "mmol/mol", "below 42 (below 69 is acceptable for planned surgery)", "high", "Taken 2 months ago: diabetes acceptably controlled for planned surgery", None, 0, origin="book", row="SR-3002"),
     R("lab.glucose", "Finger-prick glucose", 7.8, "mmol/L", "6-10 (perioperative target)", "normal", "Inside the target 6 to 10", None, 2, origin="book"),
     R("lab.hba1c.c2", "HbA1c", 82, "mmol/mol", "below 42 (below 69 is acceptable for planned surgery)", "high", "Variant C2: above 69", None, 0, origin="book", variant="C2"),
     R("lab.glucose.c2", "Finger-prick glucose", 13.4, "mmol/L", "6-10 (perioperative target)", "high", "Variant C2: high", None, 2, origin="book", variant="C2"),
     R("lab.ketones.c2", "Ketones", 0.4, "mmol/L", "below 0.6", "normal", "Variant C2: normal", None, 2, origin="book", variant="C2")],
    [S("NEWS2", "0", "All vital signs in the normal band", "book")],
    [P("c.diabetes", "optimisable", "Diabetes control and the medicine plan for the fasting day", 1,
       "HbA1c 58 is below 69 and the sugar is in the target: proceed with a medicine plan (metformin as normal; omit gliclazide today) and hourly sugar checks. In C2, HbA1c above 69 means optimise first.",
       ["Check HbA1c and today's sugar against the thresholds", "Plan the medicines for a fasting day", "Put her first on the list if possible", "Check sugar at least hourly; tell the anaesthetist"])],
    [D("c.d1", "HbA1c 58, sugar 7.8. What do you do?",
       [("Proceed: metformin as normal, omit gliclazide today, first on the list, sugar at least hourly, tell the anaesthetist", True, "Matches the book. The prescriber confirms the plan; no doses are set here."),
        ("Postpone because she is diabetic", False, "HbA1c below 69 is acceptable for planned surgery."), ("Give both tablets as usual", False, "Gliclazide while fasting could cause low sugar.")], rule="s1_diabetes_postpone"),
     D("c.d2", "Variant C2: HbA1c 82, sugar 13.4, ketones 0.4. What do you do?",
       [("Discuss with the anaesthetist or diabetes team; the usual answer is postpone and optimise", True, "HbA1c above 69 and a high sugar: planned surgery is deferred."), ("Proceed as for C1", False, "Above the threshold.")],
       rule="s1_diabetes_postpone", variant="C2")],
    "ready",
    {"correct": ["Check HbA1c and the finger-prick sugar", "Compare with 69 mmol/mol and the 6 to 10 target", "Medicine plan: metformin as normal, omit gliclazide", "First on the list; hourly sugar; tell the anaesthetist"],
     "incorrect": [bad("Lets her take gliclazide this morning", "Sugar falls to 3.4 while fasting", "Hypoglycaemia in a fasting patient", "Treat per the hypoglycaemia protocol; tell the anaesthetist")],
     "missed": ["Not checking today's sugar"], "recovery": ["Check now; act on the result"]},
    debrief(["HbA1c and sugar both checked", "Medicine plan for fasting"], ["Today's sugar not checked"], "Make a safe plan for a diabetic patient on a fasting day", "Low sugar is the immediate risk of the usual tablets",
            "HbA1c is long-term control; sugar is today", "None", "HbA1c above 69 or a sugar outside the target", "Hypoglycaemia while fasting, or surgery in poorly controlled diabetes", "Check HbA1c and sugar, then plan the medicines"),
    ["V-07"], reason="To have my gallbladder taken out.", variant_end={"C2": "postponed"})

# ---------------------------------------------------------------------------------------------------------------- VAR-S1-D
CASES["VAR-S1-D"] = case(
    "VAR-S1-D", "Patient S1-D - on a blood thinner", "S1",
    person("Mr", "Imran Sheikh", "M", 67, "retired bus driver", 4, 17, "603155"),
    {"setting": "pre-assessment", "time_now": "08:00", "surgery_time": "10:00",
     "summary": "Mr Imran, 67, has atrial fibrillation treated with apixaban and kidney function eGFR 68. When he last took apixaban decides whether surgery can proceed."},
    history("Pain under the ribs after fatty food, on and off for a year.", red_flags="No fever, no yellow eyes.", past="Atrial fibrillation (irregular heartbeat), high blood pressure.",
            medicines="Apixaban for my heartbeat, and one blood pressure tablet.", last_food="Dinner at 19:30 yesterday.", last_drink="Water at 06:30.", pregnancy="Not applicable.", origin={"complaint": "authored", "past_history": "book", "medicines": "book"},
            extra=[H("medicines", "Three days ago, as the pre-op nurse told me.", False, "book", id="last_dose.d1", ask=["ask:last dose", "ask:apixaban", "ask:blood thinner"], variant="D1"),
                   H("medicines", "This morning. I forgot what the nurse said.", False, "book", id="last_dose.d2", ask=["ask:last dose", "ask:apixaban", "ask:blood thinner"], variant="D2")]),
    [O("08:00", 78, 134, 82, 14, 97, 36.7, rhythm="irregular", note="Pulse irregular but rate 78: known, controlled atrial fibrillation.", origin="book")],
    [E("ex.pulse", "heart", "Pulse irregularly irregular, rate about 78; heart sounds normal.", True, "book"), E("ex.abdomen", "abdomen", "Soft; no tenderness.")],
    [R("lab.egfr", "eGFR", 68, "mL/min/1.73m2", "90 or above (60 to 89 is mildly reduced)", "low", "Mildly reduced: enough for the usual apixaban pause", None, 45, origin="book"),
     R("lab.ecg", "ECG", "Atrial fibrillation, rate controlled", "", "sinus rhythm", "abnormal", "Known atrial fibrillation; confirms the pulse", None, 20, origin="book")],
    [S("NEWS2", "0", "Rate 78, other values normal; irregular rhythm is not scored by NEWS2", "book")],
    [P("d.anticoag", "pathway_changing", "Anticoagulant still active: bleeding risk at surgery", 1,
       "Apixaban is usually omitted for a day or two before planned surgery with good kidneys. If he took it this morning, the drug is active and planned surgery is deferred.",
       ["Ask exactly when he last took apixaban", "Check kidney function", "Decide: three days ago means proceed; this morning means defer and re-list", "Tell the surgeon and the anaesthetist"])],
    [D("d.d1", "He says: 'Three days ago, as the pre-op nurse told me.' What now?",
       [("Stopped long enough with good kidney function: proceed; restart after surgery as the surgeon decides", True, "Variant D1 (PAUSE-type pause: 1 to 2 days with normal kidneys)."), ("Postpone anyway", False, "No reason to delay.")], variant="D1"),
     D("d.d2", "He says: 'This morning, I forgot.' What now?",
       [("The drug is still active: the surgeon and anaesthetist usually defer and re-list; reversal is not used just to make a planned operation possible", True, "Variant D2: postpone."),
        ("Proceed because the operation is minor", False, "Bleeding risk with an active anticoagulant."), ("Give a reversal agent so surgery can go ahead", False, "Not done for planned surgery.")], variant="D2"),
     D("d.d3", "Pulse irregular, rate 78. What do you do?",
       [("Known, controlled atrial fibrillation: record it and confirm with an ECG", True, "Fine for surgery."), ("Treat it as a new emergency rhythm", False, "Rate controlled and known.")])],
    "ready",
    {"correct": ["Ask exactly when he last took apixaban", "Check kidney function", "D1: proceed; D2: defer and re-list", "ECG to confirm known atrial fibrillation"],
     "incorrect": [bad("Does not ask when the last dose was", "The anaesthetist asks at Sign In and finds a dose this morning", "Surgery with an active anticoagulant", "Stop; defer and re-list")],
     "missed": ["Not noticing the irregular pulse"], "recovery": ["Feel the pulse; ECG"]},
    debrief(["Last dose asked exactly", "Kidney function used"], ["Last dose not asked"], "Is the anticoagulant still active?", "Bleeding risk at surgery", "Anticoagulant, kidney function and timing go together", "The rate-controlled atrial fibrillation",
            "A dose within the pause window", "Bleeding in surgery", "Ask exactly when the last tablet was taken"),
    ["V-08"], reason="To have my gallbladder taken out.", variant_end={"D2": "postponed"})

# ---------------------------------------------------------------------------------------------------------------- VAR-S1-G
CASES["VAR-S1-G"] = case(
    "VAR-S1-G", "Patient S1-G - ate breakfast", "S1",
    person("Ms", "Sana Farooq", "F", 39, "accountant", 7, 12, "719420"),
    {"setting": "pre-assessment", "time_now": "08:00", "surgery_time": "09:00",
     "summary": "Ms Sana, 39, says: 'I had toast and tea with milk at 07:00.' Surgery is planned for 09:00."},
    history("Attacks of pain under the ribs after meals.", red_flags="No fever, no yellow eyes.", past="None.", last_food="Toast and tea with milk at 07:00 this morning.", last_drink="Tea with milk at 07:00.", pregnancy="Last period 2 weeks ago; she agrees to a test.",
            origin={"last_food": "book", "last_drink": "book"}),
    [O("08:00", 72, 118, 74, 14, 99, 36.6, note="Baseline vital signs, all normal.", origin="authored")],
    [E("ex.abdomen", "abdomen", "Soft; no tenderness.")],
    [R("lab.upt", "Urine pregnancy test", "Negative", "", "negative", "negative", "Not pregnant", None, 20)],
    [S("Fasting", "Toast and milky tea = light meal: 6 hours needed, so not safe until 13:00", "Fasting rule: clear liquids 2 h, light meal (milk counts as food) 6 h, heavy meal 8 h", "book")],
    [P("g.fasting", "safety_blocker", "Fasting rule broken: a light meal 2 hours before surgery", 1, "A full stomach risks aspiration under anaesthetic.",
       ["Record the exact time and what she ate", "Tell the anaesthetist immediately and honestly", "Do not round the time"])],
    [D("g.d1", "She ate toast and milky tea at 07:00; surgery is at 09:00. What do you do?",
       [("Tell the anaesthetist at once: a light meal needs 6 hours, so it is not safe until 13:00; the likely outcome is the end of the list or postponement", True, "Matches the book and the ASA fasting guideline."),
        ("Say nothing, because it was only toast", False, "Milk counts as food; the rule is 6 hours."), ("Record 'fasted' to keep the list on time", False, "Falsifying the time is a safety failure.")], rule="fasting_planned")],
    "delayed",
    {"correct": ["Ask the exact time and what she ate", "Apply the 6 hour light meal rule: 13:00", "Tell the anaesthetist immediately", "Move to the end of the list or postpone"],
     "incorrect": [bad("Records 'fasted' to avoid trouble", "The anaesthetist asks at Sign In", "Aspiration under anaesthetic", "Correct the record; tell the anaesthetist")], "missed": ["Not asking about the last food"], "recovery": ["Ask and record now"]},
    debrief(["Honest report of the meal", "Rule applied"], ["Last food not asked"], "A breached fasting rule", "Aspiration risk", "Meal, milk and timing", "None", "Any food or milky drink inside the fasting window", "Aspiration pneumonitis", "Milk counts as food; record exact times"),
    ["V-09"], reason="To have my gallbladder taken out.")

# ---------------------------------------------------------------------------------------------------------------- VAR-S1-H
CASES["VAR-S1-H"] = case(
    "VAR-S1-H", "Patient S1-H - possible pregnancy", "S1",
    person("Ms", "Hina Rauf", "F", 29, "pharmacy assistant", 2, 25, "822371"),
    {"setting": "pre-assessment", "time_now": "08:00", "surgery_time": "10:00",
     "summary": "Ms Hina, 29, last period 7 weeks ago. The urine pregnancy test is positive. She may not have known; this needs private, sensitive handling."},
    history("Attacks of pain under the ribs after fatty meals.", red_flags="No fever, no yellow eyes; no vaginal bleeding; no pain in the lower tummy.", past="None.", medicines="None.", last_food="Dinner at 20:00 yesterday.", last_drink="Water at 06:30.",
            pregnancy="My last period was seven weeks ago. I did not think about it.", origin={"pregnancy": "book"}),
    [O("08:00", 78, 112, 70, 14, 99, 36.7, note="Baseline vital signs, all normal.", origin="authored")],
    [E("ex.abdomen", "abdomen", "Soft; mild tenderness under the right ribs; no lower tummy tenderness."), E("ex.shoulder", "general", "No shoulder-tip pain; not dizzy.")],
    [R("lab.upt", "Urine pregnancy test", "Positive", "", "negative", "positive", "Pregnant (about 7 weeks)", None, 20, origin="book")],
    [S("NEWS2", "0", "All vital signs in the normal band", "authored")],
    [P("h.preg", "safety_blocker", "Positive pregnancy test before planned surgery", 1, "Changes imaging, drugs, anaesthesia and timing; she has no pain or bleeding, so ectopic pregnancy is not suspected but must be kept in mind.",
       ["Tell her privately and sensitively", "Do not proceed with planned surgery", "Senior surgeon, anaesthetist and the obstetric team decide", "Safety-net advice: lower tummy pain, bleeding, shoulder-tip pain or dizziness means come straight back"])],
    [D("h.d1", "The pregnancy test is positive. What now?",
       [("Postpone the planned surgery; the senior surgeon, anaesthetist and obstetric team decide; discuss it privately and sensitively", True, "Matches the book."),
        ("Proceed because she has no pain in her lower tummy", False, "Pregnancy status changes drugs, imaging and anaesthesia."), ("Tell her in front of other patients", False, "Privacy and sensitivity are required.")]),
     D("h.d2", "What if her gallbladder trouble became urgent during the pregnancy?",
       [("Laparoscopic cholecystectomy is possible in any trimester when needed (SAGES); for non-urgent surgery the second trimester is usual", True, "ISS-0017: the book prefers the second trimester; SAGES allows any trimester when surgery is needed."),
        ("Surgery is never possible in pregnancy", False, "Incorrect.")])],
    "postponed",
    {"correct": ["Do the pregnancy test per policy", "Tell her privately and kindly", "Stop the planned surgery", "Involve the senior, anaesthetist and obstetric team", "Safety-net advice"],
     "incorrect": [bad("Does not do the pregnancy test", "The anaesthetist asks at Sign In", "Unknown pregnancy status: a hard safety failure", "Do the test and stop")], "missed": ["Not asking about the last period"], "recovery": ["Ask; test"]},
    debrief(["Test done and acted on", "Private and sensitive"], ["Last period not asked"], "A positive pregnancy test", "It changes surgery, drugs and imaging", "Test and history", "None", "A positive test", "Unplanned exposure to drugs or imaging", "Always know the pregnancy status before surgery"),
    ["V-10", "V-14"], reason="To have my gallbladder taken out.")

# ---------------------------------------------------------------------------------------------------------------- VAR-S1-J
CASES["VAR-S1-J"] = case(
    "VAR-S1-J", "Patient S1-J - the 'high potassium' that wasn't", "S1",
    person("Mr", "Kamran Javed", "M", 50, "electrician", 9, 5, "934018"),
    {"setting": "pre-assessment", "time_now": "08:00", "surgery_time": "10:00",
     "summary": "Mr Kamran, 50, is well. The pre-operative potassium comes back 6.4 'haemolysed'. His ECG and kidney function are normal."},
    history("Attacks of pain under the ribs after fatty meals.", red_flags="No fever, no yellow eyes, no weakness, no palpitations.", past="None.", medicines="None.", last_food="Dinner at 20:00 yesterday.", last_drink="Water at 06:00.", pregnancy="Not applicable.",
            origin={"complaint": "authored"}),
    [O("08:00", 70, 126, 78, 14, 98, 36.7, note="He is well; baseline vital signs normal.", origin="authored")],
    [E("ex.general", "general", "Looks well; no weakness."), E("ex.pulse", "heart", "Regular pulse; heart sounds normal.")],
    [R("lab.k1", "Potassium", 6.4, "mmol/L", "3.5-5.3", "high", "Haemolysed sample: the cells burst in the tube, so the potassium looks falsely high. Repeat.", None, 45, quality="haemolysed", origin="book"),
     R("lab.ecg", "ECG", "Normal", "", "sinus rhythm", "normal", "No peaked T waves", None, 20, origin="book"),
     R("lab.creat", "Creatinine", 84, "umol/L", "60-110", "normal", "Kidney function normal", None, 45, origin="book"),
     R("lab.k2", "Potassium (repeat)", 4.6, "mmol/L", "3.5-5.3", "normal", "Repeat sample: normal", None, 90, origin="book")],
    [S("Potassium zone", "6.4 is moderately high (6.0 to 6.4), below the 6.5 critical limit", "UKKA categories", "book")],
    [P("j.k", "time_critical", "Potassium 6.4 on a haemolysed sample in a well patient", 1, "Well patient, normal ECG and kidneys and a lab comment that the cells burst make a false result likely; it must still be repeated urgently.",
       ["Read the lab comment", "Look at the patient and check the ECG and kidney function", "Repeat the potassium urgently from a clean sample", "Tell the anaesthetist"])],
    [D("j.d1", "Potassium 6.4 'haemolysed' in a well man with a normal ECG and kidneys. What now?",
       [("Probably a false result: repeat urgently, tell the anaesthetist; the repeat is 4.6, so proceed", True, "Matches the book."), ("Treat it as true hyperkalaemia and cancel", False, "Unsupported by the patient, ECG and kidneys."),
        ("Ignore it", False, "An unrepeated high potassium cannot be ignored.")], rule=None)],
    "ready",
    {"correct": ["Read the lab comment: haemolysed", "Check the patient, ECG and kidney function", "Repeat urgently", "Tell the anaesthetist", "Repeat 4.6: proceed"],
     "incorrect": [bad("Treats the potassium without repeating", "Repeat is normal", "Needless treatment", "Stop; repeat first")], "missed": ["Not reading the lab comment"], "recovery": ["Read the comment; repeat"]},
    debrief(["Lab comment read", "Result checked against the patient"], ["Lab comment not read"], "A likely false result that still needs repeating", "A true potassium of this size can cause rhythm problems", "Sample quality, patient and ECG", "None",
            "A potassium above 6.0 whatever the sample", "Missing a true result, or needless treatment", "Read the lab comment and repeat; do not act on one implausible value"),
    ["V-15"], reason="To have my gallbladder taken out.")
